mapper.select:
SELECT mt.menu_id, mt.menu_name, mt.menu_price, mt.comment, mt.menu_status, mt.img_url,
mdt.menu_detail_id, mdt.option_id,
ot.option_id, ot.option_name, odt.option_detail_id, odt.option_detail_value, odt.option_detail_price FROM menu_tb mt LEFT OUTER JOIN menu_detail_tb mdt on (mdt.menu_id = mt.menu_id) LEFT OUTER JOIN option_tb ot on (ot.option_id = mdt.option_id) LEFT OUTER JOIN option_detail_tb odt on (odt.option_id = ot.option_id) WHERE mt.menu_id = #{menuId}
